# -*- coding: utf-8 -*-
"""
Dota 2 全 126 英雄专属机制画像与前·中·后期内置判断引擎 (hero_profiles_126.py)

核心设计原则：
1. 拒绝机械只看“伤害/推塔/死几次”，每个英雄都有独立的【强势期曲线 (timing_curve)】与【专属核心机制 (mechanism_check)】：
   - `late_hyper_carry`（大后期刷钱收割核：如敌法师、美杜莎、幽鬼、恐怖利刃、幻影长矛手、变体精灵、斯温、露娜、娜迦海妖、虚空假面、混沌骑士、幻影刺客、卓尔游侠、矮人直升机、冥魂大帝、巨魔战将、噬魂鬼、天穹守望者、炼金术士）：
     * 前中期（0-22m）身板弱、极度依赖狂战/分身/辉耀/电锤/BKB成型，此时避战刷钱、不盲目参团送节奏是【完全合理且正确】的；
     * 真正的内置考核在【25m+ 出山收割期】：吃了全队最高经济后，后期团战是否真正打出收割输出与推进？若前中期刷好钱、后期出山接管比赛则给高评价；若刷了25分钟出山即暴毙/零输出，则严判“刷满经济却未能兑现后期收割职责”。
   - `mid_tempo_brawler`（前中期干架/抓人节奏核：如斯拉克、拍拍熊、血魔、影魔、圣堂刺客、克林克兹、力丸、帕克、风暴之灵、灰烬之灵、虚无之灵、痛苦女王、哈斯卡、冥界亚龙、剃刀、伐木机、兽、齐天大圣、米波、育母蜘蛛、琼英碧灵、凯）：
     * 10-25m 是黄金强势期，绝不能当闷头大刷子；必须把第一件节奏装（跳刀/隐刀/紫怨/散失/连击刀/魔晶/BKB）转化为抓人与控图；
     * 后期考核是否补齐针对性克制装（魔晶/冰眼/金箍棒/否决/羊刀）以及是否无视野单带被抓。
   - `glass_cannon_turret`（无位移/脆皮高爆发远程炮台：如莉娜、宙斯、狙击手、天怒法师、修补匠、祈求者、光之守卫、帕格纳、殁境神蚀者）：
     * 核心职责是【把伤害灌满】：哪怕阵亡较多，只要平均每次阵亡前倾泻高额输出（每死换伤 >= 2,800 或伤害占比 >= 20%），就是兑现了炮台价值的功臣；同时给出大推推/吹风/微光等走位自救博弈建议。
   - `frontline_initiator`（三号位跳刀先手/冲脸肉盾：如斧王、半人马战行者、斯拉达、潮汐猎人、马格纳斯、玛尔斯、军团指挥官、帕吉、末日使者、昆卡、酒仙、黑暗贤者、蝙蝠骑士、小小、裂魂人、暗夜魔王、钢背兽、孽主、破晓辰星、玛西）：
     * 核心职责是【先手开团控制 + 顶前排吃伤害】：若跳刀先手控住多人、吸收全队28%+伤害后阵亡换掉敌方核心，属于“敢死开团功臣”绝不乱扣死几次的锅；若跳刀难产、空大或畏缩后排不吃伤害则严判。
   - `teamfight_ult_engine`（变蛋/墓碑/蛇棒/黑洞/树精大/萨尔框大/冰龙大/巫医大/术士大等团战阵地支点：如凤凰、不朽尸王、术士、巫医、暗影萨满、谜团、撼地者、沙王、树精卫士、干扰者、寒冬飞龙、上古巨神、杰奇洛、瘟疫法师、沉默术士、远古冰魄）：
     * 核心职责是【招牌大招/变蛋/墓碑在团战中的存活率与释放质量】：如凤凰超新星变蛋成功炸出 vs 被打碎、尸王墓碑存活率、大招流是否憋大暴毙。
   - `save_healer_support`（薄葬/神谕大/毒狗关/暗箱/全能/死骑/海民雪球/小精灵等救人保核辅助：如戴泽、神谕者、暗影恶魔、环轨百戏王、全能骑士、亚巴顿、艾欧、陈、巨牙海民、巫妖、水晶室女）：
     * 核心职责是【救人技能释放次数 + 团队治疗量 + 微光/推推/莲花救人兑现度】。
   - `zoo_split_pusher`（召唤推进与全图牵制核：如先知、兽王、狼人、德鲁伊、维萨吉、魅惑魔女、死亡先知、拉席克、龙骑士）：
     * 核心职责是【外塔/高地建筑推进转化 + 全图带线牵制空间】。
"""

from typing import Any, Dict, List, Optional, Tuple
from dota_constants_zh import HEROES_ZH


def _hp(
    short: str,
    timing_curve: str,
    roles: List[str],
    scores: Dict[str, int],
    dmg_type: str,
    synergy_tags: List[str],
    signature_abilities: List[str],
    early_rule: str,
    mid_rule: str,
    late_rule: str,
    shard_desc: str = "",
    core_item_hint: str = "",
) -> Dict[str, Any]:
    return {
        "short": short,
        "timing_curve": timing_curve,
        "roles": roles,
        "scores": scores,
        "dmg_type": dmg_type,
        "synergy_tags": synergy_tags,
        "signature_abilities": signature_abilities,
        "early_rule": early_rule,
        "mid_rule": mid_rule,
        "late_rule": late_rule,
        "shard_desc": shard_desc,
        "core_item_hint": core_item_hint,
    }


