def get_hero_profile_126(hero_id: int, pos: int = 3, hero_short_zh: str = "") -> Dict[str, Any]:
    """获取任意英雄的内置画像（126 英雄 100% 命中，含兜底保护）"""
    hid = int(hero_id or 0)
    if hid in HERO_PROFILES_126:
        return HERO_PROFILES_126[hid]
    zh_tuple = HEROES_ZH.get(hid, (hero_short_zh or f"英雄#{hid}", hero_short_zh or f"英雄#{hid}", float(pos)))
    return _hp(
        zh_tuple[0],
        "late_hyper_carry" if pos == 1 else ("mid_tempo_brawler" if pos == 2 else ("frontline_initiator" if pos == 3 else "roaming_pickoff_support")),
        ["核心位置职责执行", "前中后期节奏推进", "团战技能协同"],
        {"init": 65, "burst": 70, "tf": 75, "push": 65, "pick": 70, "late": 75, "tank": 65},
        "mixed",
        ["hard_carry"] if pos == 1 else ["aoe_teamfight"],
        [],
        "前期稳住对线补刀与状态消耗。",
        "中期围绕关键装成型节点参与小规模团战与外塔推进。",
        "后期团战盯紧关键技能释放与买活容错。",
    )


def audit_hero_mechanism_and_timing(
    p: Dict[str, Any],
    team_players: List[Dict[str, Any]],
    enemy_players: List[Dict[str, Any]],
    duration_min: float,
    won: bool,
) -> Dict[str, Any]:
    """
    针对该玩家所玩英雄的【内置强势期曲线 (timing_curve)】与【专属核心机制】进行深度审计。
    返回结构化诊断结果，供战术显微镜、个人卷宗、三阶段复盘及 Grok 4.7 提示词统一调用。
    """
    hid = int(p.get("hero_id") or 0)
    pos = int(p.get("pos") or 3)
    hero_name = p.get("hero_short_zh") or p.get("hero_name") or f"英雄#{hid}"
    prof = get_hero_profile_126(hid, pos, hero_name)
    curve = prof["timing_curve"]

    kills = int(p.get("kills") or 0)
    deaths = int(p.get("deaths") or 0)
    assists = int(p.get("assists") or 0)
    kp = float(p.get("kill_participation_pct") or 0.0)
    gpm = int(p.get("gpm") or 0)
    hdmg = int(p.get("hero_damage") or 0)
    hdmg_share = float(p.get("hero_damage_share_pct") or 0.0)
    tdmg = int(p.get("tower_damage") or 0)
    dtaken_share = float(p.get("damage_taken_share_pct") or 0.0)
    stuns = float(p.get("stuns_sec") or 0.0)
    heal = int(p.get("hero_healing") or 0)
    has_shard = bool(p.get("aghanims_shard"))

    pt = p.get("phase_telemetry") or {}
    mid_gold = int(pt.get("mid_gold_gain") or pt.get("mid_gold_gained") or 0)
    late_gold = int(pt.get("late_gold_gain") or pt.get("late_gold_gained") or 0)
    late_gold_share = float(pt.get("late_gold_share_pct") or 0.0)
    late_hdmg = int(pt.get("late_hdmg_gain") or pt.get("late_hero_damage") or 0)
    late_hdmg_share = float(pt.get("late_hdmg_share_pct") or 0.0)
    solo_pickoffs = pt.get("solo_pickoffs") or []
    low_dmg_tfs = pt.get("low_dmg_tfs") or []

    curve_zh_map = {
        "late_hyper_carry": "🌾➡️⚔️ 大后期刷钱收割核（前中期避战刷钱合理·25m+出山收割）",
        "mid_tempo_brawler": "⚡ 前中期干架节奏核（10-25m黄金强势期·严禁闷头纯刷）",
        "glass_cannon_turret": "🔥 脆皮高爆发远程炮台（考核死前灌满输出·每死换伤）",
        "frontline_initiator": "🛡️ 跳刀先手开团肉盾（考核先手控制时长与顶前排吃伤）",
        "teamfight_ult_engine": "🌋 团战阵地大招支点（考核变蛋/墓碑/团控大招存活与转化）",
        "save_healer_support": "🚑 反手救人保核辅助（考核薄葬/暗箱/禁锢/治疗救人兑现）",
        "roaming_pickoff_support": "🏹 游走抓人控图辅助（考核前中期游走控制与视野反隐）",
        "zoo_split_pusher": "🏰 召唤推进与全图牵制核（考核推塔拆迁与带线牵制空间）",
    }
    timing_curve_zh = curve_zh_map.get(curve, "核心位置标准定位")

    ab_list = p.get("ability_uses_rich") or []
    ab_summary_parts = []
    for sig in prof.get("signature_abilities") or []:
        for ab in ab_list:
            if sig in (ab.get("zh_name") or ""):
                ab_summary_parts.append(f"{ab['zh_name']}×{ab['count']}")
                break
    if not ab_summary_parts and ab_list:
        ab_summary_parts = [f"{ab['zh_name']}×{ab['count']}" for ab in ab_list[:3]]
    ab_summary_str = " / ".join(ab_summary_parts) if ab_summary_parts else "基础技能循环"

    # 1. 判断「大核前中期避战刷钱合理性 vs 后期出山收割兑现度」
    early_farm_reasonable = False
    late_harvest_fulfilled = False
    late_harvest_failed = False
    mid_tempo_wasted = False
    sacrificial_initiator_fulfilled = False
    save_support_fulfilled = False
    badges: List[str] = []
    verdict_tag = ""
    mechanism_summary = ""
    early_phase_note = prof["early_rule"]
    mid_phase_note = prof["mid_rule"]
    late_phase_note = prof["late_rule"]

    if curve == "late_hyper_carry" and pos in (1, 2):
        # 大后期刷钱核：前中期（10-25m）低参战刷钱是合理的！关键看 25m+ 是否完成收割
        if mid_gold >= 5800 or gpm >= 520:
            early_farm_reasonable = True
            mid_phase_note = (
                f"【符合{hero_name}大核特性的避战刷钱】{hero_name}前期作战弱、极度依赖核心装成型，"
                f"中期(10-25m)避开无效乱战专心刷出 +{mid_gold:,} 经济（GPM {gpm}）在策略上完全合理，核心看 25m+ 出山能否收割。"
            )
        if duration_min >= 25:
            if late_hdmg_share >= 23.0 or (won and (late_hdmg_share >= 19.0 or tdmg >= 4500)):
                late_harvest_fulfilled = True
                verdict_tag = "大核出山收割"
                badges.append(f"🌾➡️⚔️ 大核后期收割: 占后期伤{late_hdmg_share:.0f}%")
                late_phase_note = (
                    f"【教科书式大核后期收割】前中期隐忍刷钱成型后，25m+ 决胜期成功出山轰出 {late_hdmg:,} 点后期伤害"
                    f"（占全队后期伤害 {late_hdmg_share:.1f}%）+ {tdmg:,} 建筑推进，完美兑现了后期大核的收割承诺！"
                )
                mechanism_summary = late_phase_note
            elif (late_gold_share >= 21.0 or gpm >= 520) and late_hdmg_share <= 17.5:
                late_harvest_failed = True
                verdict_tag = "刷满经济后期未收割"
                badges.append(f"📉 大核刷25m未兑现收割(后期伤仅{late_hdmg_share:.0f}%)")
                late_phase_note = (
                    f"【只刷不C·后期收割违约】前中期为你让资源避战刷钱可以理解，但 25m+ 出山期你吃下全队 {late_gold_share:.1f}% 经济（+{late_gold:,} 金），"
                    f"后期团战却仅打出 {late_hdmg:,} 伤害（仅占全队后期伤害 {late_hdmg_share:.1f}%），"
                    + (f"且在 {', '.join(low_dmg_tfs[:3])} 团战中近乎零输出，" if low_dmg_tfs else "")
                    + "未能兑现大核后期接管比赛的承诺！"
                )
                mechanism_summary = late_phase_note

    elif curve == "mid_tempo_brawler" and pos in (1, 2, 3):
        # 前中期干架节奏核（如小鱼人/拍拍熊/女王/帕克/蓝猫/火猫/影魔/哈斯卡）：中期绝不能闷头纯刷！
        mid_k = int(pt.get("mid_kills") or 0)
        if duration_min >= 22 and kp < 42.0 and mid_k <= 2:
            mid_tempo_wasted = True
            verdict_tag = "节奏核闷头刷错失强势期"
            badges.append(f"⏳ 错失中期强势期(参战仅{kp:.0f}%)")
            mid_phase_note = (
                f"【错把干架节奏核当大核闷头刷】{hero_name}的核心强势期在 10-25 分钟抓人与小规模团战，"
                f"但本局中期仅斩获 {mid_k} 击杀（全场参战率 {kp:.1f}%），白白放过了英雄最强滚雪球窗口。"
            )
            mechanism_summary = mid_phase_note

    elif curve == "frontline_initiator" and pos in (3, 4):
        # 先手开团肉核：考核控制时长 + 承伤占比（哪怕死得多，只要开好团顶住伤害就是敢死开团功臣）
        if (stuns >= 35.0 or dtaken_share >= 24.0) and kp >= 55.0:
            sacrificial_initiator_fulfilled = True
            verdict_tag = "敢死先手开团顶梁柱"
            badges.append(f"🛡️ 先手开团顶伤: {dtaken_share:.0f}%承伤/{stuns:.0f}s控")
            mechanism_summary = (
                f"【先手肉核职责兑现】作为{pos}号位开团手，全场打出 {stuns:.1f} 秒硬控、扛下全队 {dtaken_share:.1f}% 伤害（参战率 {kp:.1f}%），"
                f"哪怕先手进场阵亡 {deaths} 次也是为后排炮台撑起输出空间的战略牺牲。"
            )

    elif curve == "save_healer_support" and pos in (4, 5):
        # 救人治疗辅助：考核救人技能释放 + 治疗量 + 保护道具
        item_uses = p.get("active_item_uses") or {}
        save_item_casts = sum(
            v.get("count", 0)
            for k, v in item_uses.items()
            if any(sk in k for sk in ("微光", "推推", "原力", "莲花", "吹风", "风杖", "吊坠", "梅肯", "卫士"))
        )
        if heal >= 3500 or save_item_casts >= 8 or stuns >= 45.0 or kp >= 68.0:
            save_support_fulfilled = True
            verdict_tag = "保核救人兑现"
            badges.append(f"🚑 保核救人: 参战{kp:.0f}%/救人道具{save_item_casts}次")
            mechanism_summary = (
                f"【救人辅助机制兑现】全场高频释放 {ab_summary_str}，配合救人道具按出 {save_item_casts} 次（治疗 {heal:,} / 控制 {stuns:.1f}s / 参战率 {kp:.1f}%），"
                f"在团战后排尽全力拉扯保护核心。"
            )

    # 2. 检查该英雄是否有「必出命脉魔晶 (shard_desc)」却在 25m+ 仍未购买
    missing_mandatory_shard = False
    if prof.get("shard_desc") and "必出" in prof.get("shard_desc", "") and duration_min >= 25 and not has_shard:
        missing_mandatory_shard = True
        badges.append(f"🚫 {duration_min:.0f}m未出命脉魔晶!")

    dossier = build_hero_matchup_dossier(p, team_players, enemy_players, duration_min, won)

    return {
        "hero_id": hid,
        "hero_short_zh": hero_name,
        "timing_curve": curve,
        "timing_curve_zh": timing_curve_zh,
        "roles": prof["roles"],
        "signature_abilities_summary": ab_summary_str,
        "shard_desc": prof.get("shard_desc", ""),
        "core_item_hint": prof.get("core_item_hint", ""),
        "early_farm_reasonable": early_farm_reasonable,
        "late_harvest_fulfilled": late_harvest_fulfilled,
        "late_harvest_failed": late_harvest_failed,
        "mid_tempo_wasted": mid_tempo_wasted,
        "sacrificial_initiator_fulfilled": sacrificial_initiator_fulfilled,
        "save_support_fulfilled": save_support_fulfilled,
        "missing_mandatory_shard": missing_mandatory_shard,
        "verdict_tag": verdict_tag,
        "badges": badges,
        "mechanism_summary": mechanism_summary,
        "early_phase_note": early_phase_note,
        "mid_phase_note": mid_phase_note,
        "late_phase_note": late_phase_note,
        "hero_matchup_dossier": dossier,
    }


